describe("doctests of sympy.polys.polyroots", () => {
  // a primitive result that no library call returned
  //   roots(x**2 - 1, x)
  //   => {-1: 1, 1: 1}
  it.todo("roots(x**2 - 1, x)");
  // a primitive result that no library call returned
  //   roots(p)
  //   => {-1: 1, 1: 1}
  it.todo("roots(p)");
  // a primitive result that no library call returned
  //   roots(Poly(p, x))
  //   => {-sqrt(y): 1, sqrt(y): 1}
  it.todo("roots(Poly(p, x))");
  // a primitive result that no library call returned
  //   roots(x**2 - y, x)
  //   => {-sqrt(y): 1, sqrt(y): 1}
  it.todo("roots(x**2 - y, x)");
  // a primitive result that no library call returned
  //   roots([1, 0, -1])
  //   => {-1: 1, 1: 1}
  it.todo("roots([1, 0, -1])");
  // a primitive result that no library call returned
  //   roots((x-1)*(x**5-x+1), x)
  //   => {1: 1}
  it.todo("roots((x-1)*(x**5-x+1), x)");
  it("roots(x**7-3*x**2+1, x)", () => {
    expect(sympyStr(new Map())).toBe('{}');
  });
  it("sum(roots(f, x).values()) == degree(f, x)", () => {
    expect(sympyStr(Rational.of(3n, 1n, { gcd: 1n }).equals(Rational.of(3n, 1n, { gcd: 1n })))).toBe('True');
  });
  it("sum(roots(f, x).values()) == degree(f, x) (2)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("root_factors(x**2 - y, x)", () => {
    const [x, y] = symbols('x y');
    const v1 = rootFactors(add(pow(x, Rational.of(2n, 1n, { gcd: 1n })), mul(Rational.of(-1n, 1n, { gcd: 1n }), y)), x);
    expect(sympyStr([at(v1, 0), at(v1, 1)])).toBe('[x - sqrt(y), x + sqrt(y)]');
  });
});

